CREATE TABLE books_fast_hashes (fast_hash TEXT PRIMARY KEY, book_id INTEGER);
CREATE TABLE books_impl(  id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, first_title_letter TEXT, author TEXT, firstauthor TEXT, first_author_letter TEXT, series TEXT, numinseries INTEGER, size INTEGER, creationtime INTEGER NOT NULL DEFAULT 0, updated INTEGER NOT NULL DEFAULT 0, date_added TEXT,  ts_added INTEGER,  isbn TEXT,  hidden INTEGER INTEGER NOT NULL DEFAULT 0,  sort_title TEXT,  resource_id TEXT);
CREATE TABLE books_settings( bookid INTEGER, profileid INTEGER, position TEXT, position_ts INTEGER, cpage INTEGER, npage INTEGER, opentime INTEGER, completed INTEGER, completed_ts INTEGER, favorite INTEGER, favorite_ts INTEGER, custom TEXT, PRIMARY KEY(bookid,profileid), FOREIGN KEY(bookid) references books_impl(id), FOREIGN KEY(profileid) references profiles(id));
CREATE TABLE bookshelfs( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, is_deleted INTEGER, ts INTEGER, uuid TEXT, UNIQUE(name) ON CONFLICT FAIL);
CREATE TABLE bookshelfs_books( bookshelfid INTEGER, bookid INTEGER, ts INTEGER, is_deleted INTEGER, PRIMARY KEY(bookshelfid, bookid));
CREATE TABLE booktogenre(bookid INTEGER, genreid INTEGER, PRIMARY KEY(bookid, genreid), FOREIGN KEY(bookid) references books_impl(id), FOREIGN KEY(genreid) references genres(id));
CREATE TABLE file_props (  fast_hash TEXT,  prop_type INTEGER,  value TEXT, PRIMARY KEY(fast_hash,prop_type));
CREATE TABLE files( id INTEGER PRIMARY KEY AUTOINCREMENT,  storageid INTEGER,  folder_id INTEGER,  book_id INTEGER,  filename TEXT, size INTEGER, modification_time INTEGER,  fast_hash TEXT,  ext TEXT, FOREIGN KEY(storageid) REFERENCES storages(id), FOREIGN KEY(folder_id) REFERENCES folders(id), FOREIGN KEY(book_id) REFERENCES books_impl(id) );
CREATE TABLE folders( id INTEGER PRIMARY KEY AUTOINCREMENT, storageid INTEGER, name TEXT, FOREIGN KEY(storageid) REFERENCES storages(id), UNIQUE(storageid, name) ON CONFLICT FAIL);
CREATE TABLE genres(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, UNIQUE(name));
CREATE TABLE migrated ( id INTEGER PRIMARY KEY);
CREATE TABLE profiles(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT);
CREATE VIRTUAL TABLE search USING fts5(book_id UNINDEXED, title, author);
CREATE TABLE social( bookid INTEGER, profileid INTEGER, completed INTEGER, reading INTEGER, liked INTEGER, status INTEGER, stars INTEGER, PRIMARY KEY(bookid,profileid), FOREIGN KEY(bookid) references books_impl(id), FOREIGN KEY(profileid) references profiles(id));
CREATE TABLE storages(id INTEGER PRIMARY KEY, type INTEGER, name TEXT, sync_account_id INTEGER);
CREATE TABLE sync_accounts ( id INTEGER PRIMARY KEY, name TEXT, sync_cursor TEXT, sync_ts INTEGER, is_active INTEGER);
CREATE TABLE sync_data( b_id INTEGER, profile_id INTEGER, data_type INTEGER, ts INTEGER, PRIMARY KEY (b_id, profile_id, data_type));
CREATE TABLE tags2( timestampid INTEGER NOT NULL REFERENCES timestamps(id), type INTEGER NOT NULL, profileid INTEGER NOT NULL REFERENCES profiles(id), title TEXT, path TEXT, author TEXT, recommendator TEXT, is_viewed INTEGER, params TEXT,  notification_app_id TEXT,  PRIMARY KEY(timestampid, type, profileid));
CREATE TABLE timestamps( id INTEGER PRIMARY KEY AUTOINCREMENT, time INTEGER NOT NULL, description TEXT);
CREATE TABLE version(id INTEGER PRIMARY KEY);
CREATE INDEX b_firstauthor_title_id_1  ON books_impl (firstauthor ASC, sort_title ASC, id ASC);
CREATE INDEX b_title_id_1  ON books_impl (sort_title ASC, id ASC);
CREATE INDEX books_ts_added_1 ON books_impl (ts_added DESC, sort_title ASC, id ASC);
CREATE INDEX bookshelfs_uuid_idx ON bookshelfs(uuid);
CREATE INDEX file_ext  ON files (ext ASC );
CREATE INDEX files_book_id ON files(book_id);
CREATE INDEX files_name ON files(filename);
CREATE INDEX folders_name_idx ON folders(name);
CREATE INDEX timestampsididx ON timestamps(id);
CREATE TRIGGER completed_ts_insert AFTER INSERT ON books_settings  BEGIN     UPDATE books_settings SET completed_ts = strftime('%s', 'now') WHERE bookid = NEW.bookid  AND profileid = NEW.profileid; END;
CREATE TRIGGER completed_ts_update AFTER UPDATE ON books_settings WHEN NEW.completed <> OLD.completed BEGIN     UPDATE books_settings SET completed_ts = strftime('%s', 'now') WHERE bookid = NEW.bookid  AND profileid = NEW.profileid; END;
CREATE TRIGGER date_added_unsert AFTER INSERT ON books_impl FOR EACH ROW  BEGIN UPDATE books_impl SET date_added = date(ts_added, 'unixepoch')  WHERE id = NEW.id;  END;
CREATE TRIGGER date_added_update AFTER UPDATE ON books_impl FOR EACH ROW  WHEN NEW.ts_added != OLD.ts_added AND NEW.date_added = OLD.date_added BEGIN  UPDATE books_impl SET date_added = date(ts_added, 'unixepoch')  WHERE id = NEW.id; END;
CREATE TRIGGER trigger_on_delete_books_impl AFTER DELETE ON books_impl FOR EACH ROW BEGIN   DELETE FROM search WHERE book_id = OLD.id;  END;
CREATE TRIGGER trigger_on_insert_books_impl AFTER INSERT ON books_impl FOR EACH ROW  BEGIN  INSERT INTO search (book_id, title, author) VALUES (NEW.id, NEW.title, NEW.author); END;
CREATE TRIGGER trigger_on_update_books_impl AFTER UPDATE ON books_impl FOR EACH ROW WHEN NEW.title != OLD.title OR NEW.author != OLD.author BEGIN  UPDATE search SET title = NEW.title, author = NEW.author WHERE book_id = NEW.id;  END;
